import sys

data = sys.stdin.read().split()
q = int(data[0])
cnt = {}
out = []
p = 1
for _ in range(q):
    op = data[p]; x = int(data[p + 1]); p += 2
    if op == 'ADD':
        cnt[x] = cnt.get(x, 0) + 1
    elif op == 'REMOVE':
        if cnt.get(x, 0) > 0:
            cnt[x] -= 1
    else:
        line = []
        for m in sorted(cnt):
            line.extend([m] * cnt[m])
        out.append(str(line[x % len(line)]) if line else '-1')
print('\n'.join(out))

